#include <iostream>
using namespace std;

class Queue {
    private:
        int *arr;
        int front, rear, capacity, size;

    public:
        // Constructor to initialize the queue
        Queue(int capacity) {
            this->capacity = capacity;
            this->front = this->rear = -1;
            this->size = 0;
            this->arr = new int[capacity];
        }

        // Function to check if the queue is empty
        bool isEmpty() {
            return (size == 0);
        }

        // Function to check if the queue is full
        bool isFull() {
            return (size == capacity);
        }

        // Function to add an element to the queue
        void enqueue(int data) {
            if (isFull()) {
                cout << "Queue is full. Cannot add more elements." << endl;
                return;
            }
            if (isEmpty()) {
                front = rear = 0;
                arr[rear] = data;
            } else {
                rear = (rear + 1) % capacity;
                arr[rear] = data;
            }
            size++;
        }

        // Function to remove an element from the queue
        int dequeue() {
            if (isEmpty()) {
                cout << "Queue is empty. Cannot remove elements." << endl;
                return -1;
            }
            int temp = arr[front];
            if (front == rear) {
                front = rear = -1;
            } else {
                front = (front + 1) % capacity;
            }
            size--;
            return temp;
        }

        // Function to get the front element of the queue
        int getFront() {
            if (isEmpty()) {
                cout << "Queue is empty." << endl;
                return -1;
            }
            return arr[front];
        }

        // Function to get the rear element of the queue
        int getRear() {
            if (isEmpty()) {
                cout << "Queue is empty." << endl;
                return -1;
            }
            return arr[rear];
        }

        // Function to print the queue
        void printQueue() {
            if (isEmpty()) {
                cout << "Queue is empty." << endl;
                return;
            }
            int temp = front;
            for (int i = 0; i < size; i++) {
                cout << arr[temp] << " ";
                temp = (temp + 1) % capacity;
            }
            cout << endl;
        }
};

int main() {
    Queue q(5);
    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);
    q.enqueue(4);
    q.enqueue(5);
    q.printQueue();  // Output: 1 2 3 4 5
    cout << q.getFront() << endl;  // Output: 1
    cout << q.getRear() << endl;  // Output: 5
    q.dequeue();
    q.printQueue();  // Output: 2 3 4 5
    return 0;
}
```

**String Reverse in C++**
=========================

### Description

This C++ code demonstrates a simple function to reverse a given string.

### Code
```cpp
#include <iostream>
#include <string>

// Function to reverse a string
std::string reverseString(const std::string& str) {
    std::string reversedStr = str;
    int left = 0;
    int right = str.length() - 1;

    while (left < right) {
        // Swap characters at left and right indices
        char temp = reversedStr[left];
        reversedStr[left] = reversedStr[right];
        reversedStr[right] = temp;

        // Move towards the center
        left++;
        right--;
    }

    return reversedStr;
}

int main() {
    // Example usage
    std::string originalStr = "Hello, World!";
    std::cout << "Original String: " << originalStr << std::endl;

    std::string reversedStr = reverseString(originalStr);
    std::cout << "Reversed String: " << reversedStr << std::endl;

    return 0;
}
```

### Explanation

1. The `reverseString` function takes a `const std::string&` as input and returns the reversed string.
2. It uses a two-pointer approach, starting from the beginning and end of the string, and swaps characters until the pointers meet in the middle.
3. In the `main` function, we demonstrate the usage of `reverseString` with an example string.

### Output

```
Original String: Hello, World!
Reversed String: !dlroW ,olleH
```
